    menu: "Menu", searchStatus: "La ricerca apre il catalogo sorgente in una nuova scheda.", placeholder: "felpa, sneakers, link prodotto…", quick: "Esplora:", issue: "LA SELEZIONE FINDQC", issueNo: "NUMERO 01 · 2026", editorNote: "NOTA EDITORIALE", editorBody: "Parti dalla scheda esatta. Confronta ciò che è visibile. Decidi con prove.", proofs: [["06", "prodotti con fonte"], ["05", "lingue dell’interfaccia"], ["01:01", "corrispondenza immagine-link"]], process: ["SCOPRI", "CONFRONTA", "CONTROLLA QC", "APRI LA SCHEDA ESATTA"],
    findsIntro: "Ogni anteprima usa l’immagine della propria pagina di destinazione. I prezzi USD sono approssimativi e vanno verificati dal vivo.", priceNote: "Conversione USD approssimativa · verifica", productNames: ["Sneakers rétro basse", "Maglione in mohair", "Felpa minimal", "Orologio classico in acciaio", "Figura da collezione", "Maglia da partita"], productCategories: ["Scarpe", "Maglioni", "Felpe", "Accessori", "Casa e oggetti", "Maglie"], methodKicker: "02 / METODO", methodTitle: "Tre controlli prima del clic", methodLink: "Apri la guida QC completa", method: [["Conferma l’identità", "Verifica tipo, colore, taglia e componenti prima dei piccoli dettagli."], ["Leggi le prove", "Usa più angoli, misure e registri. Una sola bella foto non basta."], ["Verifica dal vivo", "Apri la fonte esatta e ricontrolla prezzo, disponibilità, rotta e restrizioni."]], fieldKicker: "03 / NOTA PRATICA", fieldTitle: "Come leggere le foto QC senza indovinare", fieldText: "Una sequenza pratica per identità, angoli, forma, allineamento, colore, misure, difetti, peso e decisione finale.", readGuide: "Leggi la guida completa", fieldCaption: "Guarda due volte. Decidi una.",
    findsPage: { eyebrow: "Catalogo con fonte esatta", title: "Prodotti", intro: "Sfoglia una selezione compatta o cerca nel catalogo completo. Ogni immagine e azione corrisponde alla pagina di destinazione esatta.", all: "Tutti", empty: "Nessun prodotto corrispondente. Usa la ricerca per il catalogo completo." },
    qc: { eyebrow: "Flusso di controllo", title: "Guida QC", intro: "Usa sempre lo stesso ordine per separare le prove importanti dal rumore visivo e spiegare meglio la decisione.", cta: "Leggi la guida completa", card: "SCHEDA DECISIONE QC", complete: "controlli prima della spedizione", checklist: "CHECKLIST", checklistTitle: "Dall’identità alla decisione finale", checks: [["Identità", "Articolo, variante, colore e taglia"], ["Copertura", "Abbastanza angoli nitidi"], ["Forma", "Simmetria e proporzioni"], ["Costruzione", "Cuciture, hardware e bordi"], ["Misure", "Dimensioni critiche"], ["Decisione", "Spedisci, ricontrolla, cambia o restituisci"]], noteTitle: "Prova, non garanzia", note: "Le foto QC riducono l’incertezza ma non provano autenticità, durata, legalità d’importazione o stato finale. Verifica scheda e regole della destinazione." },
    shipping: { eyebrow: "Pianificazione del pacco", title: "Note di spedizione", intro: "Stima peso reale e volumetrico, poi verifica la rotta dopo il consolidamento. Il pacco finale determina il peso fatturabile.", cards: [["Peso reale", "Peso misurato dopo l’imballaggio. Protezioni e scatole possono cambiarlo."], ["Peso volumetrico", "Calcolo basato sulle dimensioni. Una scatola grande e leggera può costare di più."], ["Restrizioni di rotta", "La disponibilità dipende da destinazione, tipo, dimensioni e regole attuali."], ["Dogana e tasse", "Le regole d’importazione variano per destinazione e possono cambiare."]], formula: "FORMULA DI LAVORO", formulaTitle: "Peso fatturabile = il valore idoneo maggiore", actual: "Peso reale del pacco", vs: "contro", volume: "Peso volumetrico calcolato", formulaNote: "Usalo solo per pianificare. Applica divisore e arrotondamenti della rotta attiva." },
    articlesPage: { eyebrow: "Conoscenza pratica su ricerca e QC", title: "Articoli SEO e guide", intro: "Articoli indipendenti e utili, con pulsanti chiari verso pagine complete. Ogni guida copre un intento di ricerca diverso.", read: "Leggi l’articolo completo", updated: "Aggiornato il 27 agosto 2026" }, article: { back: "Tutti gli articoli SEO", reviewed: "Revisionato il 27 agosto 2026", independent: "Ricerca indipendente", inGuide: "IN QUESTA GUIDA", summary: "Riepilogo pratico", browse: "Vedi i prodotti", ready: "Pronto a controllare una scheda?", readyText: "Apri la pagina sorgente esatta e applica i controlli della guida alle prove visibili." },
    faqTitle: "Domande frequenti", faqEyebrow: "Limiti chiari, risposte utili", faqIntro: "Cosa fa l’interfaccia, cosa significano i dati e cosa va ancora verificato.", faqs: [["FindQC vende prodotti?", "No. È un’interfaccia indipendente; le azioni aprono schede esterne."], ["I prezzi sono finali?", "No. Sono conversioni USD approssimative; cambio, opzioni, stock e costi cambiano."], ["Una foto QC garantisce la qualità?", "No. È una prova visiva di un record, non della costruzione nascosta."], ["Perché ogni scheda apre una pagina specifica?", "Immagine e destinazione devono coincidere; ogni scheda usa l’immagine della pagina esatta."], ["Posso cercare con un link?", "Sì. Incolla parola chiave, ID o link sorgente."], ["Le informazioni di spedizione sono garantite?", "No. Rotta, peso, costi, dogana e tempi dipendono dalle condizioni attuali."]],
