const enArticles = [
  { slug: "how-to-read-qc-photos", title: "How to Read QC Photos Without Guessing", description: "A repeatable inspection order for identity, coverage, shape, construction, measurements and the final ship-or-return decision.", readTime: "12 min read", summary: "Confirm the correct item first, check whether the photo set covers every critical area, compare shape before tiny details, use measurements for fit, and end with one explicit action.", sections: [
    ["Start with identity", "Confirm the product type, selected color, size label and included parts before hunting for small defects. Keep the live source listing beside the warehouse photos. If the wrong item or variant arrived, fine cosmetic details no longer change the decision. A consistent identity-first order also prevents reviewers from being distracted by lighting, packaging or one attractive angle."],
    ["Check photo coverage", "Useful evidence needs enough angles. Footwear normally needs both sides, front, heel, outsole, overhead view and size label. Clothing benefits from front, back, tags, graphics, cuffs, seams and measurements. When a critical area is blurred or missing, request a focused image before international shipping instead of assuming the hidden area is acceptable."],
    ["Read shape before logos", "Overall proportions often expose a problem faster than extreme zoom. Compare paired items on the same visual line and look at toe shape, panel position, sleeve length, pocket alignment or symmetry. Perspective can distort one frame, so confirm a suspected issue from another angle. A difference that disappears when the camera moves is more likely perspective than construction."],
    ["Use measurements correctly", "A size tag confirms what was packed, not how it fits. Compare chest width, garment length, waist, inseam or insole length with an item you already own. Use the same measurement method on both items. Rulers held above a curved surface can create false readings, so ask for a flat, focused measurement when the dimension controls fit."],
    ["Separate cosmetic and structural issues", "Loose threads, removable dust and packaging marks are not equivalent to open seams, broken hardware, missing parts or deep scratches. Decide in advance which defects justify an exchange or return. Structural damage, incorrect specifications and problems likely to worsen during shipping should carry more weight than variations visible only under heavy zoom."],
    ["Finish with one action", "End with ship, request another check, exchange or return—and record the reason in one sentence. QC photos reduce uncertainty but cannot prove authenticity, durability, import legality or final delivery condition. Verify the live listing, current service rules and destination law before spending money."]
  ]},
  { slug: "search-product-link-id-keyword", title: "Product Link, Item ID or Keyword? A Better Search Workflow", description: "Choose the search input that preserves the strongest match and avoid wasting time on broad, ambiguous results.", readTime: "10 min read", summary: "Use an exact source link when available, an item ID when the system recognizes it, and a precise keyword query only when no stronger identifier exists.", sections: [
    ["Rank inputs by precision", "An exact source link normally carries more identity than an item ID, and an item ID carries more identity than a generic keyword. Start with the strongest identifier you already have. Broad terms such as shoes or hoodie are useful for discovery, but poor for confirming one specific listing because many unrelated records can share those words."],
    ["Clean the source link", "Copy the direct product page rather than a tracking redirect, social share wrapper or image URL. Remove accidental spaces and check that the link opens the intended item in a normal browser. If the source page has changed or disappeared, preserve the title, selected option and screenshots before searching for a replacement."],
    ["Use item IDs carefully", "An item ID can be efficient when it belongs to the catalog being searched. Numbers from another marketplace, an order record or a warehouse system may refer to something else. Pair the ID with one visual or textual check—such as title, main image or selected variant—before assuming the result is exact."],
    ["Write discriminating keywords", "When no link or ID works, combine item type with the most distinctive visible attributes: material, silhouette, color family, graphic placement or model reference. Avoid stuffing every possible synonym into one query. Start narrow, inspect results, then remove one term at a time if nothing useful appears."],
    ["Confirm the destination", "A convincing thumbnail is not enough. Open the final page and compare the main image, options, visible construction and current availability. The destination of every FindQC card is deliberately matched to its displayed image, but users should still verify the live source because listings and inventory can change."],
    ["Keep a small research record", "Save the exact URL, item ID, date checked and the option that interested you. This makes later QC comparison easier and prevents confusion if the title or thumbnail changes. Historical research helps retrace a decision, but it never replaces the current listing."]
  ]},
  { slug: "actual-vs-volumetric-weight", title: "Actual vs Volumetric Weight: Plan a Parcel Before Shipping", description: "Understand the two weight figures that can affect international parcel cost and what to verify after consolidation.", readTime: "11 min read", summary: "Plan with both measured and dimensional weight, reduce avoidable volume where appropriate, then recalculate using the exact live route rules after packing.", sections: [
    ["Understand actual weight", "Actual weight is the measured mass of the packed parcel. It can change when items are consolidated, boxes are removed or protective material is added. A product-page estimate is not the final billable figure because the shipping parcel includes outer packaging and any services selected at the warehouse."],
    ["Understand volumetric weight", "Volumetric or dimensional weight converts package size into a weight-like number. A large light carton may therefore cost more than a smaller heavier one. The divisor and rounding method vary by route, so do not rely on one universal formula or an old successful parcel."],
    ["Identify volume drivers", "Shoe boxes, rigid packaging, oversized accessories and protective frames can create unused space. Removing packaging may reduce volume, but it can also reduce protection or resale value. Decide which packaging is essential before submitting the parcel rather than choosing the smallest box automatically."],
    ["Compare eligible routes", "A lower headline rate is not always the lower final price. Check weight bands, minimum charges, size limits, restricted-item rules, fuel or remote-area fees and destination availability. The same parcel can be calculated differently across routes, especially near a rounding boundary."],
    ["Recheck after consolidation", "Use single-item weights only for an early estimate. Once the warehouse has packed the final parcel, review measured weight and external dimensions again. If either figure looks implausible, request a reweigh or packaging photo before payment when the service supports it."],
    ["Treat customs separately", "Shipping weight does not determine customs treatment by itself. Declaration rules, taxes, prohibited items and documentation depend on destination law and current carrier policies. Verify the live route and official destination guidance; past delivery is not a guarantee of future treatment. Keep the commercial description, quantity and supporting records consistent with the actual contents, and never use a shipping-cost estimate as legal guidance. If the destination or carrier wording is unclear, pause and consult the current official rule before submitting the parcel. This final check belongs beside the cost calculation, but it remains a separate compliance decision."]
  ]}
];

const articleTranslations = {
  de: [
    { title: "QC-Fotos lesen, ohne zu raten", description: "Eine wiederholbare Prüfreihenfolge für Identität, Bildabdeckung, Form, Verarbeitung, Maße und die Versandentscheidung.", readTime: "12 Min. Lesezeit", summary: "Zuerst den richtigen Artikel bestätigen, dann Bildabdeckung, Form, Verarbeitung und Maße prüfen und mit einer eindeutigen Aktion abschließen.", sections: [["Mit der Identität beginnen", "Prüfe Artikeltyp, Farbe, Größenetikett und enthaltene Teile, bevor du kleine Mängel suchst. Halte das Live-Angebot neben den Lagerfotos offen. Ist Artikel oder Variante falsch, ändern feine kosmetische Details die Entscheidung nicht."], ["Bildabdeckung prüfen", "Gute Belege zeigen alle kritischen Bereiche aus mehreren Winkeln. Fehlt ein Bereich oder ist er unscharf, fordere vor dem internationalen Versand ein gezieltes Foto an."], ["Form vor Logos lesen", "Gesamtproportionen zeigen Probleme oft schneller als starker Zoom. Vergleiche Symmetrie, Paneele, Ärmellänge oder Taschen und bestätige Auffälligkeiten aus einem zweiten Winkel."], ["Maße richtig nutzen", "Ein Etikett bestätigt die gepackte Größe, nicht die Passform. Vergleiche flach gemessene Breite, Länge, Taille oder Einlegesohle mit einem eigenen Referenzstück."], ["Kosmetisch oder strukturell", "Lose Fäden und Staub sind nicht dasselbe wie offene Nähte, defekte Beschläge oder fehlende Teile. Strukturelle Schäden und falsche Spezifikationen wiegen schwerer."], ["Mit einer Aktion enden", "Wähle Versand, Nachprüfung, Umtausch oder Rückgabe und notiere den Grund. QC-Fotos reduzieren Unsicherheit, garantieren aber weder Echtheit noch Haltbarkeit oder Lieferung."]]},
    { title: "Produktlink, Artikel-ID oder Stichwort? Der bessere Suchablauf", description: "Wähle die Eingabe mit der stärksten Identität und vermeide breite, mehrdeutige Treffer.", readTime: "10 Min. Lesezeit", summary: "Nutze zuerst den exakten Quelllink, danach eine erkannte Artikel-ID und nur ohne stärkere Kennung eine präzise Stichwortsuche.", sections: [["Eingaben nach Präzision ordnen", "Ein direkter Produktlink enthält meist mehr Identität als eine ID, eine ID mehr als ein allgemeines Stichwort. Beginne mit der stärksten Kennung."], ["Quelllink bereinigen", "Kopiere die direkte Produktseite statt Tracking-Weiterleitung, Social-Wrapper oder Bild-URL. Prüfe, ob der Link den richtigen Artikel öffnet."], ["IDs vorsichtig verwenden", "Nummern aus anderen Marktplätzen, Bestellungen oder Lagersystemen können etwas anderes bedeuten. Gleiche Titel, Hauptbild oder Variante ab."], ["Unterscheidende Stichwörter", "Kombiniere Artikeltyp mit Material, Silhouette, Farbfamilie oder Motivposition. Starte eng und entferne Begriffe schrittweise."], ["Zielseite bestätigen", "Ein passendes Thumbnail genügt nicht. Öffne die Seite und vergleiche Hauptbild, Optionen, sichtbare Konstruktion und Bestand."], ["Recherche festhalten", "Speichere URL, ID, Prüfdatum und gewünschte Option. Das erleichtert den späteren QC-Vergleich, ersetzt aber nie das aktuelle Angebot."]]},
    { title: "Tatsächliches vs. Volumengewicht: Paket vor dem Versand planen", description: "Verstehe beide Gewichtswerte und prüfe sie nach der Konsolidierung erneut.", readTime: "11 Min. Lesezeit", summary: "Plane mit Mess- und Volumengewicht, reduziere unnötiges Volumen sinnvoll und rechne nach dem Packen mit den Live-Regeln der Route neu.", sections: [["Tatsächliches Gewicht", "Es ist die gemessene Masse des fertigen Pakets und ändert sich durch Konsolidierung, entfernte Kartons oder Schutzmaterial."], ["Volumengewicht", "Es wandelt Paketmaße in einen Gewichtswert um. Große leichte Kartons können dadurch teurer sein; Divisor und Rundung unterscheiden sich je Route."], ["Volumentreiber erkennen", "Schuhkartons, starre Verpackungen und Schutzrahmen erzeugen Leerraum. Entfernen kann Kosten senken, aber Schutz oder Wiederverkaufswert reduzieren."], ["Routen vergleichen", "Prüfe Gewichtsstufen, Mindestgebühren, Größenlimits, Beschränkungen und Zuschläge. Eine niedrige Grundrate ist nicht immer der niedrigste Endpreis."], ["Nach Konsolidierung prüfen", "Einzelgewichte sind nur frühe Schätzungen. Nach dem Packen gemessenes Gewicht und Außenmaße erneut kontrollieren und Unplausibles nachmessen lassen."], ["Zoll getrennt behandeln", "Gewicht allein bestimmt keine Zollbehandlung. Erklärung, Steuer und Verbote richten sich nach Zielrecht und aktuellen Carrier-Regeln."]]}],
  es: [
    { title: "Cómo leer fotos QC sin adivinar", description: "Un orden repetible para identidad, cobertura, forma, construcción, medidas y decisión final.", readTime: "12 min de lectura", summary: "Confirma el artículo correcto, revisa la cobertura, compara la forma antes de detalles mínimos, mide y termina con una acción explícita.", sections: [["Empieza por la identidad", "Comprueba tipo, color, talla y piezas incluidas antes de buscar defectos pequeños. Mantén abierta la ficha de origen junto a las fotos."], ["Revisa la cobertura", "Las pruebas útiles muestran las zonas críticas desde varios ángulos. Si falta una zona, solicita una foto enfocada antes del envío."], ["Lee la forma antes que los logotipos", "Las proporciones generales revelan problemas más rápido que un zoom extremo. Confirma cualquier diferencia desde otro ángulo."], ["Usa bien las medidas", "La etiqueta no demuestra ajuste. Compara medidas planas con una prenda o plantilla que ya tengas y usa el mismo método."], ["Distingue cosmético y estructural", "Polvo e hilos sueltos no equivalen a costuras abiertas, piezas rotas o componentes ausentes."], ["Termina con una acción", "Elige enviar, volver a revisar, cambiar o devolver y anota el motivo. Las fotos reducen incertidumbre, no garantizan autenticidad ni entrega."]]},
    { title: "¿Enlace, ID o palabra clave? Un mejor flujo de búsqueda", description: "Elige la entrada que conserva la coincidencia más fuerte y evita resultados ambiguos.", readTime: "10 min de lectura", summary: "Usa enlace exacto si existe, después un ID reconocido y palabras precisas solo cuando no haya identificador mejor.", sections: [["Ordena por precisión", "Un enlace directo suele aportar más identidad que un ID, y un ID más que una palabra genérica."], ["Limpia el enlace", "Copia la página directa, no un redireccionamiento, envoltorio social o URL de imagen. Comprueba que abre el artículo correcto."], ["Usa IDs con cuidado", "Números de otro mercado, pedido o almacén pueden referirse a otra cosa. Contrasta título, imagen o variante."], ["Escribe palabras distintivas", "Combina tipo con material, silueta, color o posición del gráfico. Empieza estrecho y elimina un término cada vez."], ["Confirma el destino", "Una miniatura convincente no basta. Abre la página y compara imagen, opciones, construcción y disponibilidad."], ["Guarda un registro", "Conserva URL, ID, fecha y opción. Facilita la comparación QC, pero no sustituye la ficha actual."]]},
    { title: "Peso real frente a volumétrico: planifica el paquete", description: "Comprende las dos cifras que pueden afectar al coste y qué revisar tras consolidar.", readTime: "11 min de lectura", summary: "Planifica con ambos pesos, reduce volumen evitable cuando convenga y recalcula con las reglas activas tras embalar.", sections: [["Peso real", "Es la masa medida del paquete terminado y cambia con consolidación, cajas retiradas y protección añadida."], ["Peso volumétrico", "Convierte dimensiones en una cifra de peso. Una caja grande y ligera puede costar más; divisor y redondeo varían."], ["Qué crea volumen", "Cajas de zapatos, embalajes rígidos y protectores generan espacio. Quitarlos puede reducir coste y también protección."], ["Compara rutas", "Revisa bandas, mínimos, límites, artículos restringidos y recargos. La tarifa inicial más baja no siempre gana."], ["Verifica tras consolidar", "Los pesos individuales son estimaciones. Revisa peso y medidas finales y pide un nuevo control si parecen improbables."], ["Separa aduanas", "El peso no determina por sí solo el trato aduanero. Declaración, impuestos y prohibiciones dependen del destino."]]}],
  fr: [
    { title: "Lire les photos QC sans deviner", description: "Un ordre reproductible pour l’identité, la couverture, la forme, la fabrication, les mesures et la décision.", readTime: "12 min de lecture", summary: "Confirmez d’abord le bon article, vérifiez la couverture, la forme, les mesures, puis terminez par une action explicite.", sections: [["Commencer par l’identité", "Vérifiez type, couleur, taille et éléments inclus avant les petits défauts. Gardez la fiche source ouverte à côté des photos."], ["Vérifier la couverture", "Les preuves utiles montrent toutes les zones critiques sous plusieurs angles. Demandez une photo ciblée si une zone manque."], ["Lire la forme avant les logos", "Les proportions générales révèlent souvent un problème plus vite qu’un zoom extrême. Confirmez depuis un second angle."], ["Bien utiliser les mesures", "L’étiquette ne prouve pas la coupe. Comparez des mesures à plat avec un article que vous possédez déjà."], ["Cosmétique ou structurel", "Poussière et fils libres ne valent pas une couture ouverte, une pièce cassée ou un élément manquant."], ["Finir par une action", "Choisissez expédier, revérifier, échanger ou retourner et notez la raison. Les photos réduisent l’incertitude sans garantir authenticité ou livraison."]]},
    { title: "Lien produit, identifiant ou mot-clé ? Une meilleure recherche", description: "Choisissez l’entrée qui conserve la correspondance la plus forte.", readTime: "10 min de lecture", summary: "Préférez le lien source exact, puis un identifiant reconnu, et utilisez des mots précis seulement sans meilleur repère.", sections: [["Classer par précision", "Un lien direct apporte généralement plus d’identité qu’un identifiant, lui-même plus précis qu’un mot générique."], ["Nettoyer le lien", "Copiez la page directe, pas une redirection de suivi, un partage social ou une URL d’image. Vérifiez l’article ouvert."], ["Utiliser les identifiants avec prudence", "Un numéro d’une autre place de marché, commande ou entrepôt peut désigner autre chose. Comparez titre, image ou variante."], ["Écrire des mots distinctifs", "Combinez type, matière, silhouette, couleur ou placement du motif. Commencez étroit et retirez un terme à la fois."], ["Confirmer la destination", "Une miniature convaincante ne suffit pas. Ouvrez la page et comparez image, options, construction et stock."], ["Conserver une trace", "Gardez URL, identifiant, date et option. Cela aide le QC ultérieur sans remplacer la fiche actuelle."]]},
    { title: "Poids réel ou volumétrique : préparer un colis", description: "Comprenez les deux chiffres qui peuvent affecter le coût et ce qu’il faut vérifier après consolidation.", readTime: "11 min de lecture", summary: "Planifiez avec les deux poids, réduisez le volume évitable avec discernement et recalculez selon la ligne active après emballage.", sections: [["Poids réel", "C’est la masse mesurée du colis fini. Consolidation, retrait des boîtes et protection peuvent la modifier."], ["Poids volumétrique", "Il convertit les dimensions en poids. Un grand carton léger peut coûter plus cher ; diviseur et arrondi varient."], ["Sources de volume", "Boîtes à chaussures, emballages rigides et protections créent du vide. Les retirer peut réduire coût et protection."], ["Comparer les lignes", "Vérifiez tranches, minimums, limites, restrictions et suppléments. Le tarif affiché le plus bas ne gagne pas toujours."], ["Revérifier après consolidation", "Les poids unitaires sont des estimations. Contrôlez poids et dimensions finaux et demandez une nouvelle mesure si nécessaire."], ["Traiter la douane séparément", "Le poids ne détermine pas seul la douane. Déclaration, taxes et interdictions dépendent de la destination."]]}],
  it: [
    { title: "Come leggere le foto QC senza indovinare", description: "Un ordine ripetibile per identità, copertura, forma, costruzione, misure e decisione finale.", readTime: "12 min di lettura", summary: "Conferma l’articolo corretto, controlla la copertura, confronta la forma prima dei dettagli, misura e termina con un’azione chiara.", sections: [["Parti dall’identità", "Controlla tipo, colore, taglia e parti incluse prima dei difetti minori. Tieni la scheda sorgente accanto alle foto."], ["Controlla la copertura", "Le prove utili mostrano ogni zona critica da più angoli. Se manca un’area, chiedi una foto mirata prima della spedizione."], ["Leggi la forma prima dei loghi", "Le proporzioni generali mostrano problemi più velocemente di uno zoom estremo. Conferma da un secondo angolo."], ["Usa bene le misure", "L’etichetta non prova la vestibilità. Confronta misure piatte con un capo o una soletta che possiedi."], ["Cosmetico o strutturale", "Polvere e fili sciolti non equivalgono a cuciture aperte, hardware rotto o parti mancanti."], ["Termina con un’azione", "Scegli spedisci, ricontrolla, cambia o restituisci e annota il motivo. Le foto riducono l’incertezza, non garantiscono autenticità o consegna."]]},
    { title: "Link, ID o parola chiave? Un flusso di ricerca migliore", description: "Scegli l’input che conserva la corrispondenza più forte ed evita risultati ambigui.", readTime: "10 min di lettura", summary: "Usa il link esatto, poi un ID riconosciuto e parole precise solo quando non esiste un identificatore migliore.", sections: [["Ordina per precisione", "Un link diretto contiene in genere più identità di un ID, e un ID più di una parola generica."], ["Pulisci il link", "Copia la pagina diretta, non redirect, wrapper social o URL immagine. Controlla che apra l’articolo corretto."], ["Usa gli ID con cautela", "Numeri di altri marketplace, ordini o magazzini possono indicare altro. Confronta titolo, immagine o variante."], ["Scrivi parole distintive", "Combina tipo, materiale, silhouette, colore o posizione grafica. Parti stretto e rimuovi un termine alla volta."], ["Conferma la destinazione", "Una miniatura convincente non basta. Apri la pagina e confronta immagine, opzioni, costruzione e stock."], ["Conserva un record", "Salva URL, ID, data e opzione. Aiuta il confronto QC, ma non sostituisce la scheda attuale."]]},
    { title: "Peso reale o volumetrico: pianifica il pacco", description: "Comprendi le due cifre che possono incidere sul costo e cosa verificare dopo il consolidamento.", readTime: "11 min di lettura", summary: "Pianifica con entrambi i pesi, riduci il volume evitabile con criterio e ricalcola con le regole attive dopo l’imballaggio.", sections: [["Peso reale", "È la massa misurata del pacco finito e cambia con consolidamento, rimozione di scatole e protezioni."], ["Peso volumetrico", "Converte le dimensioni in peso. Una scatola grande e leggera può costare di più; divisore e arrotondamento variano."], ["Fonti di volume", "Scatole, confezioni rigide e protezioni creano spazio vuoto. Rimuoverle può ridurre costo e protezione."], ["Confronta le rotte", "Controlla fasce, minimi, limiti, restrizioni e supplementi. La tariffa iniziale più bassa non sempre vince."], ["Ricontrolla dopo il consolidamento", "I pesi singoli sono stime. Verifica peso e dimensioni finali e chiedi una nuova misurazione se sembrano errati."], ["Tratta la dogana separatamente", "Il peso non determina da solo la dogana. Dichiarazione, tasse e divieti dipendono dalla destinazione."]]}]
};

const baseArticles = Object.fromEntries(Object.keys(copy).map((lang) => [lang, enArticles.map((article, index) => ({
  ...article,
  ...(lang === "en" ? {} : articleTranslations[lang][index]),
}))]));

const parityReadyArticles = Object.fromEntries(Object.keys(baseArticles).map((lang) => [lang, applyParityArticles(extendArticles(baseArticles[lang], lang), lang)]));

export const seoArticles = Object.fromEntries(Object.keys(parityReadyArticles).map((lang) => [
  lang,
  [...applyArticleParityBoost(parityReadyArticles[lang], lang, parityReadyArticles.en), localizedRequirementsBriefArticles[lang], localizedUseCaseArticles[lang]],
]));

